package com.aula.fixa.ui.adapter.os;
import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.ImageView;import android.widget.TextView;
import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.aula.fixa.R;import com.aula.fixa.domain.model.os.TarefaOS;import java.util.ArrayList;import java.util.List;
public final class ExecucaoTarefaAdapter extends RecyclerView.Adapter<ExecucaoTarefaAdapter.Holder>{
 public interface Listener{void details(TarefaOS t);void options(View v,TarefaOS t);}private final List<TarefaOS> rows=new ArrayList<>();private final Listener listener;private final boolean canManage;
 public ExecucaoTarefaAdapter(Listener l){this(l,true);}public ExecucaoTarefaAdapter(Listener l,boolean canManage){listener=l;this.canManage=canManage;}public void submit(List<TarefaOS> x){rows.clear();if(x!=null)rows.addAll(x);notifyDataSetChanged();}
 @NonNull @Override public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_ops_manager_planning_task,p,false));}
 @Override public void onBindViewHolder(@NonNull Holder h,int pos){TarefaOS t=rows.get(pos);boolean done="CONCLUIDA".equals(t.status);h.title.setText(t.titulo==null||t.titulo.trim().isEmpty()?"Tarefa sem título":t.titulo.trim());h.description.setText(t.descricao==null?"":t.descricao);h.status.setBackgroundTintList(android.content.res.ColorStateList.valueOf(androidx.core.content.ContextCompat.getColor(h.item.getContext(),done?R.color.app_status_done:R.color.app_text_muted)));h.item.setContentDescription((done?"Concluída: ":"Não iniciada: ")+h.title.getText());h.item.setOnClickListener(v->listener.details(t));h.more.setVisibility(canManage?View.VISIBLE:View.GONE);if(canManage)h.more.setOnClickListener(v->listener.options(v,t));}
 @Override public int getItemCount(){return rows.size();}
 static final class Holder extends RecyclerView.ViewHolder{final View item,status;final TextView title,description;final ImageView more;Holder(View v){super(v);item=v;status=v.findViewById(R.id.executionTaskStatus);title=v.findViewById(R.id.planningTaskTitle);description=v.findViewById(R.id.planningTaskDescription);more=v.findViewById(R.id.planningTaskMore);}}
}
